  if (mem._poseHist.length >= 8) {
    var oldestIndex = Math.max(0, mem._poseHist.length - 13);
    var p0 = mem._poseHist[oldestIndex];
    var p1 = mem._poseHist[mem._poseHist.length - 1];

    var span = p1.t - p0.t;
    if (!(span > 0)) span = 0.05 * (mem._poseHist.length - 1);

    var mdx = p1.x - p0.x;
    var mdy = p1.y - p0.y;
    var moved = Math.sqrt(mdx * mdx + mdy * mdy);
    var moveRate = moved / Math.max(0.05, span);

