  mem._lastX = px;
  mem._lastY = py;
  mem._lastRawH = rawH;

  var targetIndex = Math.floor(num(obs.targetIndex, 0));
  if (targetIndex < 0) targetIndex = 0;

  var tx = num(obs.targetX, NaN);
  var ty = num(obs.targetY, NaN);

  if (
    (!finite(tx) || !finite(ty)) &&
    obs.targets &&
    typeof obs.targets.length === "number" &&
    obs.targets.length > targetIndex
