  var targetDist = distance(px, py, tx, ty);
  var targetKey =
    String(targetIndex) + ":" +
    String(Math.round(tx * 3)) + ":" +
    String(Math.round(ty * 3));

  if (mem._targetKey !== targetKey) {
    mem._targetKey = targetKey;

    mem._mode = 0;
    mem._modeTicks = 0;
    mem._lastMode = 0;
    mem._cooldown = 0;

    mem._bypass = 0;
    mem._followSide = -1;
    mem._lastBypass = 0;
    mem._followSwitches = 0;

    mem._hitX = px;
    mem._hitY = py;
    mem._hitDist = targetDist;
    mem._modeBest = targetDist;
    mem._modeNoProgress = 0;

    mem._bestDist = targetDist;
    mem._noProgress = 0;
    mem._noMotion = 0;
    mem._recoveries = 0;

