  if (
    courseFresh &&
    mem._mode === 0 &&
    forwardSpeed > 0.45 &&
    Math.abs(mem._turnOut) < 0.12 &&
    Math.abs(mem._hRate) < 70 &&
    d[2] > 3.0 &&
    d[1] > 1.0 &&
    d[3] > 1.0
  ) {
    var measuredBias =
      wrapDeg(mem._courseH - mem._hSmooth);

    if (Math.abs(measuredBias) < 70) {
