  }

  var rayAngles = [-60, -30, 0, 30, 60];

  function boundaryRay(relativeAngle) {
    var margin = 0.72;
    var x0 = margin;
    var x1 = 40 - margin;
    var y0 = margin;
    var y1 = 40 - margin;

    if (px < x0 || px > x1 || py < y0 || py > y1) {
      return 0;
    }

    var a = (navH + relativeAngle) * Math.PI / 180;
    var ux = Math.cos(a);
    var uy = Math.sin(a);
    var best = 10;
    var q;

    if (ux > 0.000001) {
      q = (x1 - px) / ux;
      if (q >= 0) best = Math.min(best, q);
    } else if (ux < -0.000001) {
      q = (x0 - px) / ux;
      if (q >= 0) best = Math.min(best, q);
    }

    if (uy > 0.000001) {
      q = (y1 - py) / uy;
      if (q >= 0) best = Math.min(best, q);
    } else if (uy < -0.000001) {
      q = (y0 - py) / uy;
      if (q >= 0) best = Math.min(best, q);
    }

