  }

  for (i = 0; i < 5; i++) {
    d[i] = Math.min(d[i], boundaryRay(rayAngles[i]));
  }

  var edgeBand = 2.25;
  var awayX = 0;
  var awayY = 0;

  if (px < edgeBand) awayX += edgeBand - px;
  if (px > 40 - edgeBand) awayX -= px - (40 - edgeBand);
  if (py < edgeBand) awayY += edgeBand - py;
  if (py > 40 - edgeBand) awayY -= py - (40 - edgeBand);

