  }

  var targetBearing =
    Math.atan2(ty - py, tx - px) * 180 / Math.PI;

  var targetError = wrapDeg(targetBearing - aimH);
  var absTargetError = Math.abs(targetError);
  var targetClose = targetDist < 1.06;

  function risk(value, threshold) {
    return clamp((threshold - value) / threshold, 0, 1);
  }

  var rightSpace =
    0.68 * Math.min(d[1], 4) +
    0.32 * Math.min(d[0], 4);

  var leftSpace =
    0.68 * Math.min(d[3], 4) +
    0.32 * Math.min(d[4], 4);

  var rightRisk =
    0.68 * risk(d[1], 1.55) +
    0.32 * risk(d[0], 1.20);

  var leftRisk =
    0.68 * risk(d[3], 1.55) +
    0.32 * risk(d[4], 1.20);

  var sideNearMin = Math.min(d[1], d[3]);
  var sideOuterMin = Math.min(d[0], d[4]);

  var frontLook = clamp(
    2.60 + Math.min(0.85, forwardSpeed * 0.55),
    2.50,
    3.50
  );

  var sideDanger =
    sideNearMin < 0.88 ||
    sideOuterMin < 0.76;

  var sideHard =
    sideNearMin < 0.55 ||
    sideOuterMin < 0.48;

  var sideExtreme =
    sideNearMin < 0.40 ||
    sideOuterMin < 0.36;

  var frontBlocked =
    d[2] < frontLook ||
    (
      d[2] < 2.30 &&
      (
        d[1] < 0.78 ||
        d[3] < 0.78
