    );

  var frontHard =
    d[2] < 0.72 ||
    (
      d[2] < 1.05 &&
      sideNearMin < 0.72
    );

  if (
    targetClose &&
    d[2] > 1.40 &&
    !sideHard &&
    !boundaryUrgent
  ) {
    frontBlocked = false;
  }

  if (targetDist < mem._bestDist - 0.07) {
    mem._bestDist = targetDist;
    mem._noProgress = 0;
  } else {
    mem._noProgress++;
  }

  var recentMoved = 0;

  if (mem._poseHist.length >= 10) {
    var moveP0 = mem._poseHist[
      Math.max(0, mem._poseHist.length - 11)
    ];
    var moveP1 = mem._poseHist[
      mem._poseHist.length - 1
    ];

