  } else {
    mem._noMotion = Math.max(0, mem._noMotion - 2);
  }

  if (mem._cooldown > 0) {
    mem._cooldown--;
  }

  if (mem._mode === 1 || mem._mode === 2) {
    mem._modeTicks++;
  } else {
    mem._modeTicks = 0;
  }

  function pathSpace(direction) {
    return direction > 0 ? leftSpace : rightSpace;
  }

  function chooseBypass() {
    if (
      boundaryUrgent &&
      Math.abs(boundaryError) > 12
    ) {
      return boundaryError > 0 ? 1 : -1;
    }

    if (leftSpace > rightSpace + 0.30) {
      return 1;
    }

    if (rightSpace > leftSpace + 0.30) {
      return -1;
    }

    if (
      targetError > 22 &&
      leftSpace > 0.85
    ) {
      return 1;
    }

    if (
      targetError < -22 &&
      rightSpace > 0.85
    ) {
      return -1;
    }

    if (mem._lastBypass !== 0) {
