    mem._mode = 1;
    mem._modeTicks = 0;
    mem._bypass = direction;
    mem._followSide = -direction;
    mem._lastBypass = direction;
    mem._followSwitches = 0;

    mem._hitX = px;
    mem._hitY = py;
    mem._hitDist = targetDist;
    mem._modeBest = targetDist;
    mem._modeNoProgress = 0;
  }

  function beginRecovery(direction) {
    if (direction !== 1 && direction !== -1) {
      direction = chooseBypass();
    }

    mem._mode = 2;
    mem._modeTicks = 0;
    mem._recoverDir = direction;
    mem._recoveries++;
    mem._noMotion = 0;
    mem._modeNoProgress = 0;
  }

  var restartedFollow = false;
  var switchedFollow = false;
  var leftFollow = false;
  var enteredRecovery = false;

  if (
    mem._mode === 2 &&
    mem._modeTicks > 42
  ) {
    beginFollow(mem._recoverDir);
    restartedFollow = true;
  }

  if (mem._mode === 1) {
    if (targetDist < mem._modeBest - 0.08) {
      mem._modeBest = targetDist;
      mem._modeNoProgress = 0;
    } else {
      mem._modeNoProgress++;
    }

    if (
      mem._modeTicks > 28 &&
      mem._followSwitches < 1 &&
      frontHard
