      var selectedSpace =
        mem._bypass > 0 ? leftSpace : rightSpace;

      var alternateSpace =
        mem._bypass > 0 ? rightSpace : leftSpace;

      if (
        selectedSpace < 0.90 &&
        alternateSpace > selectedSpace + 0.28
      ) {
        mem._bypass = -mem._bypass;
        mem._followSide = -mem._bypass;
        mem._lastBypass = mem._bypass;
        mem._followSwitches++;

        mem._hitX = px;
        mem._hitY = py;
        mem._hitDist = targetDist;
        mem._modeBest = targetDist;
        mem._modeNoProgress = 0;
        mem._modeTicks = 0;

