        (d[1] - d[0]) * ((angle + 60) / 30);
    }

    if (angle <= 0) {
      return d[1] +
        (d[2] - d[1]) * ((angle + 30) / 30);
    }

    if (angle <= 30) {
      return d[2] +
        (d[3] - d[2]) * (angle / 30);
    }

    return d[3] +
      (d[4] - d[3]) * ((angle - 30) / 30);
  }

  if (
    mem._mode === 1 &&
    !switchedFollow &&
    !restartedFollow
  ) {
    var targetSector = sectorDistance(targetError);
    var clearNeed = Math.min(
      5.5,
      Math.max(1.20, targetDist - 0.25)
    );

    var lineClear =
      absTargetError < 58 &&
      targetSector > clearNeed &&
      d[2] > 1.20 &&
      !sideHard &&
      !boundaryUrgent &&
      !frontBlocked;

    var passed =
      targetDist < mem._hitDist - 0.22;

    var movedFromHit =
      distance(px, py, mem._hitX, mem._hitY) > 0.82;

    var closeEnough =
      targetClose &&
      d[2] > 0.82 &&
      !sideHard;

    if (
      mem._modeTicks > 30 &&
      movedFromHit &&
      (
        (lineClear && passed) ||
        closeEnough
