    ) {
      shouldRecover = true;
    }

    if (
      mem._mode === 1 &&
      (
        (
          mem._modeTicks > 230 &&
          mem._modeNoProgress > 150
        ) ||
        (
          mem._modeTicks > 70 &&
          mem._noMotion > 115
        ) ||
        (
          mem._modeTicks > 310 &&
          mem._modeNoProgress > 110
        )
