  var obstacleSeen =
    frontBlocked ||
    frontHard ||
    sideHard ||
    boundaryUrgent;

  if (
    mem._mode === 0 &&
    !leftFollow &&
    !enteredRecovery &&
    obstacleSeen &&
    (
      mem._cooldown <= 0 ||
      frontHard ||
      sideHard ||
      boundaryUrgent
