  }

  var targetSteer =
    clamp(targetError * 0.0035, -0.30, 0.30);

  var desiredTurn = 0;
  var base = 0;
  var frontFactor = clamp(
    (frontLook - d[2]) /
    Math.max(0.60, frontLook - 0.70),
    0,
    1
