  if (mem._mode === 2) {
    if (mem._modeTicks < 13) {
      base = absoluteSpeed > 0.12 ? -0.22 : 0;
      desiredTurn = 0;
    } else {
      base = 0.08;
      desiredTurn = activeBypass * 0.36;
