    base = 0.42;

    desiredTurn =
      targetSteer * 0.10 +
      0.07 * (rightRisk - leftRisk) +
      boundaryTurn * 0.68;

    var followSide = mem._followSide;
    if (followSide !== 1 && followSide !== -1) {
      followSide = -activeBypass;
