    var wallNear =
      followSide < 0 ? d[1] : d[3];

    var wallOuter =
      followSide < 0 ? d[0] : d[4];

    var wallDistance =
      0.70 * Math.min(wallNear, 3) +
      0.30 * Math.min(wallOuter, 3);

    var desiredWallDistance = 1.02;

    if (wallDistance < 3.0) {
      var wallError = clamp(
        (desiredWallDistance - wallDistance) / 0.70,
