  var rightAvoid = 0;
  var leftAvoid = 0;

  if (d[1] < 1.20) {
    rightAvoid = Math.max(
      rightAvoid,
      0.38 * risk(d[1], 1.20)
    );
  }

  if (d[0] < 1.10) {
    rightAvoid = Math.max(
      rightAvoid,
      0.30 * risk(d[0], 1.10)
    );
  }

  if (d[3] < 1.20) {
    leftAvoid = Math.max(
      leftAvoid,
      0.38 * risk(d[3], 1.20)
    );
  }

  if (d[4] < 1.10) {
    leftAvoid = Math.max(
      leftAvoid,
      0.30 * risk(d[4], 1.10)
