    } else {
      desiredTurn = Math.min(desiredTurn, -0.38);
    }
  }

  if (mem._mode !== 2) {
    if (targetDist < 6.0) base = Math.min(base, 0.58);
    if (targetDist < 3.5) base = Math.min(base, 0.45);
    if (targetDist < 2.3) base = Math.min(base, 0.32);
    if (targetDist < 1.60) base = Math.min(base, 0.22);
    if (targetDist < 1.12) base = Math.min(base, 0.10);
    if (targetDist < 0.84) base = Math.min(base, 0.03);
  }

  if (d[2] < frontLook) {
    base = Math.min(base, 0.44);
  }

  if (d[2] < 2.15) {
    base = Math.min(base, 0.30);
  }

  if (d[2] < 1.45) {
    base = Math.min(base, 0.18);
  }

  if (d[2] < 1.00) {
    base = Math.min(base, 0.08);
  }

  if (d[2] < 0.68) {
    base = Math.min(
      base,
      forwardSpeed > 0.14 ? -0.16 : 0
    );
  }

  if (sideNearMin < 1.05 || sideOuterMin < 0.90) {
    base = Math.min(base, 0.36);
  }

  if (sideNearMin < 0.80 || sideOuterMin < 0.70) {
    base = Math.min(base, 0.18);
