}

function clamp(v, min, max) {
  return v < min ? min : (v > max ? max : v);
}

function applyDeadband(v) {
  if (Math.abs(v) < 0.08) return 0;
  if (Math.abs(v) < 0.2) return v > 0 ? 0.2 : -0.2;
  return v;
}

function updateMap(mem, x, y, hTrue, rays) {
  const R = GRID_RES;
  const cgx = Math.floor(x / R), cgy = Math.floor(y / R);
  if (cgx >= 0 && cgx < GRID_W && cgy >= 0 && cgy < GRID_H) {
    const cid = cgy * GRID_W + cgx;
    if (mem.grid[cid] === 0) mem.grid[cid] = 2;
  }
  for (let i = 0; i < 5; i++) {
    const rawD = rays[i];
    const maxD = Math.min(rawD, 9.5);
    const rad = (hTrue + RAY_ANGLES[i]) * Math.PI / 180;
    const dx = Math.cos(rad);
    const dy = Math.sin(rad);
    for (let s = 0; s < maxD - 0.2; s += 0.25) {
      const px = x + dx * s;
      const py = y + dy * s;
      if (px < 0 || px >= 40 || py < 0 || py >= 40) break;
      const gx = Math.floor(px / R);
      const gy = Math.floor(py / R);
      if (gx < 0 || gx >= GRID_W || gy < 0 || gy >= GRID_H) continue;
      const id = gy * GRID_W + gx;
      if (mem.grid[id] === 0) mem.grid[id] = 2;
    }
    if (rawD < 9.5) {
      const px = x + dx * rawD;
      const py = y + dy * rawD;
      if (px >= 0 && px < 40 && py >= 0 && py < 40) {
        const gx = Math.floor(px / R);
        const gy = Math.floor(py / R);
        if (gx >= 0 && gx < GRID_W && gy >= 0 && gy < GRID_H) {
          const id = gy * GRID_W + gx;
          mem.grid[id] = 1;
        }
      }
    }
  }
}

function planPath(mem, sx, sy, tx, ty) {
  const startX = Math.floor(sx / GRID_RES);
  const startY = Math.floor(sy / GRID_RES);
  let goalX = Math.floor(tx / GRID_RES);
  let goalY = Math.floor(ty / GRID_RES);
  if (startX < 0 || startX >= GRID_W || startY < 0 || startY >= GRID_H) return null;
  if (goalX < 0) goalX = 0;
  if (goalX >= GRID_W) goalX = GRID_W - 1;
  if (goalY < 0) goalY = 0;
  if (goalY >= GRID_H) goalY = GRID_H - 1;
  const start = startY * GRID_W + startX;
  const goal = goalY * GRID_W + goalX;
  if (start === goal) return [{ x: sx, y: sy }];
  const N = GRID_W * GRID_H;
  const gScore = new Float32Array(N).fill(Infinity);
  const came = new Int32Array(N).fill(-1);
  const open = [];
  const openF = [];
  function push(node, f) {
    open.push(node);
    openF.push(f);
    let i = open.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (openF[p] <= openF[i]) break;
      const tn = open[p]; open[p] = open[i]; open[i] = tn;
      const tf = openF[p]; openF[p] = openF[i]; openF[i] = tf;
      i = p;
    }
  }
  function pop() {
    const top = open[0];
    const last = open.pop();
    const lastF = openF.pop();
    if (open.length > 0) {
      open[0] = last;
      openF[0] = lastF;
      let i = 0;
      while (true) {
        const l = i * 2 + 1;
        const r = i * 2 + 2;
        let smallest = i;
        if (l < open.length && openF[l] < openF[smallest]) smallest = l;
        if (r < open.length && openF[r] < openF[smallest]) smallest = r;
        if (smallest === i) break;
        const tn = open[i]; open[i] = open[smallest]; open[smallest] = tn;
        const tf = openF[i]; openF[i] = openF[smallest]; openF[smallest] = tf;
        i = smallest;
      }
    }
    return top;
  }
  function heur(x1, y1, x2, y2) {
    const dx = Math.abs(x1 - x2);
    const dy = Math.abs(y1 - y2);
    return (dx + dy) + (Math.SQRT2 - 2) * Math.min(dx, dy);
  }
  gScore[start] = 0;
  push(start, heur(startX, startY, goalX, goalY));
  let iter = 0;
  while (open.length > 0 && iter++ < 15000) {
    const cur = pop();
    if (cur === goal) break;
    const cx = cur % GRID_W;
    const cy = Math.floor(cur / GRID_W);
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const nx = cx + dx;
        const ny = cy + dy;
        if (nx < 0 || nx >= GRID_W || ny < 0 || ny >= GRID_H) continue;
        const nid = ny * GRID_W + nx;
        if (mem.grid[nid] === 1 && nid !== goal) continue;
        let step = (dx !== 0 && dy !== 0) ? 1.41421356 : 1;
        if (mem.grid[nid] === 0) step += 0.4;
        const tentative = gScore[cur] + step;
        if (tentative < gScore[nid]) {
          came[nid] = cur;
          gScore[nid] = tentative;
          push(nid, tentative + heur(nx, ny, goalX, goalY));
        }
      }
    }
  }
  if (came[goal] === -1 && goal !== start) return null;
  const path = [];
  let cur = goal;
  while (cur !== -1) {
    const cx = cur % GRID_W;
    const cy = Math.floor(cur / GRID_W);
    path.push({ x: (cx + 0.5) * GRID_RES, y: (cy + 0.5) * GRID_RES });
    if (cur === start) break;
    cur = came[cur];
  }
  path.reverse();
  path[0] = { x: sx, y: sy };
  return path;
}

function act(obs, mem) {
  if (!mem.init) {
    mem.init = true;
    mem.grid = new Uint8Array(GRID_W * GRID_H);
    mem.bias = 0;
    mem.biasCount = 0;
    mem.lastBiasT = obs.t;
    mem.fx = obs.x;
    mem.fy = obs.y;
    mem.lastFx = obs.x;
    mem.lastFy = obs.y;
    mem.lastHeading = obs.heading;
    mem.lastTargetIndex = -1;
    mem.path = null;
    mem.pathIndex = 0;
    mem.lastPlan = -1;
    mem.lastProgress = obs.t;
    mem.lastDist = 1e9;
    mem.lastTheta = 0;
    mem.recoverUntil = 0;
    mem.recoverSteer = 90;
  }
  const t = obs.t;
  mem.fx += 0.5 * (obs.x - mem.fx);
  mem.fy += 0.5 * (obs.y - mem.fy);
  const px = mem.fx, py = mem.fy;

  if (t - mem.lastBiasT > 0.2) {
    const dx = px - mem.lastFx;
    const dy = py - mem.lastFy;
    const dist = Math.hypot(dx, dy);
    if (dist > 0.15 && obs.speed > 0.15 && Math.abs(norm180(obs.heading - mem.lastHeading)) < 8) {
      const moveHeading = Math.atan2(dy, dx) * 180 / Math.PI;
      const biasObs = norm180(obs.heading - moveHeading);
      if (mem.biasCount < 10) {
        mem.bias = (mem.bias * mem.biasCount + biasObs) / (mem.biasCount + 1);
      } else {
        mem.bias = 0.98 * mem.bias + 0.02 * biasObs;
      }
      mem.biasCount++;
    }
    mem.lastBiasT = t;
    mem.lastFx = px;
    mem.lastFy = py;
    mem.lastHeading = obs.heading;
  }
  const hTrue = norm180(obs.heading - mem.bias);
  updateMap(mem, px, py, hTrue, obs.rays);

  const tx = obs.targetX, ty = obs.targetY;
  const distToTarget = Math.hypot(tx - px, ty - py);

  if (obs.targetIndex !== mem.lastTargetIndex) {
    mem.lastTargetIndex = obs.targetIndex;
    mem.path = null;
    mem.pathIndex = 0;
    mem.lastProgress = t;
    mem.lastDist = distToTarget;
  }

  if (t - mem.lastPlan > 0.5 || mem.path === null) {
    mem.path = planPath(mem, px, py, tx, ty) || [];
    mem.pathIndex = 0;
    mem.lastPlan = t;
  }

  let aimX = tx, aimY = ty;
  if (mem.path.length > 0) {
    while (mem.pathIndex < mem.path.length - 1 &&
           Math.hypot(px - mem.path[mem.pathIndex].x, py - mem.path[mem.pathIndex].y) < 0.7) {
      mem.pathIndex++;
    }
    aimX = mem.path[mem.pathIndex].x;
    aimY = mem.path[mem.pathIndex].y;
  }

  const desiredAngle = Math.atan2(aimY - py, aimX - px) * 180 / Math.PI;
  const err = norm180(desiredAngle - hTrue);

  let bestTheta = err;
  let bestScore = -1e9;
  for (let th = -180; th <= 180; th += 5) {
    let score = Math.cos((th - err) * Math.PI / 180);
    let danger = 0;
    for (let i = 0; i < 5; i++) {
      const d = obs.rays[i];
      if (d < 3.0) {
        const diff = Math.abs(norm180(th - RAY_ANGLES[i]));
        if (diff < 90) {
          danger += (3.0 - d) * Math.exp(-(diff * diff) / 900) * 3.0;
        }
      }
    }
    score -= danger * 0.5;
    if (mem.lastTheta !== undefined) {
      score += Math.cos((th - mem.lastTheta) * Math.PI / 180) * 0.1;
    }
    if (score > bestScore) {
      bestScore = score;
      bestTheta = th;
    }
  }

  let minRay = 10;
  for (let i = 0; i < 5; i++) minRay = Math.min(minRay, obs.rays[i]);
  let targetSpeed = 1.8;
  if (minRay < 0.8) targetSpeed = 0.1;
  else if (minRay < 1.5) targetSpeed = 0.5;
  else if (minRay < 2.5) targetSpeed = 1.0;
  if (Math.abs(err) > 45) targetSpeed = Math.min(targetSpeed, 0.3);
  else if (Math.abs(err) > 20) targetSpeed = Math.min(targetSpeed, 0.8);
  if (distToTarget < 1.5) targetSpeed = Math.min(targetSpeed, 0.5);
  if (bestScore < -0.5) targetSpeed = Math.min(targetSpeed, 0.3);

  if (distToTarget < mem.lastDist - 0.05) {
    mem.lastDist = distToTarget;
    mem.lastProgress = t;
  }
  if (t - mem.lastProgress > 2.5 && distToTarget > 1.2) {
    mem.recoverUntil = t + 1.5;
    mem.lastProgress = t;
    mem.recoverSteer = (obs.rays[0] + obs.rays[1] > obs.rays[4] + obs.rays[3]) ? 90 : -90;
  }
  if (mem.recoverUntil > t) {
    bestTheta = mem.recoverSteer;
    targetSpeed = -0.4;
  } else if (obs.distanceAhead < 0.5 && obs.speed < 0.2) {
    targetSpeed = -0.3;
    bestTheta = (obs.rays[0] + obs.rays[1] > obs.rays[3] + obs.rays[4]) ? -45 : 45;
  }

  let base = 0.6 * targetSpeed + 0.8 * (targetSpeed - obs.speed);
  base = clamp(base, -1, 1);
  const eRad = bestTheta * Math.PI / 180;
  let turn = clamp(eRad * 1.5, -0.9, 0.9);
  let left = base - turn;
  let right = base + turn;
  left = applyDeadband(left);
  right = applyDeadband(right);
  left = clamp(left, -1, 1);
  right = clamp(right, -1, 1);

  mem.lastTheta = bestTheta;
  return { left, right };
}

const RES = 0.25;
const GW = 160;
const GH = 160;
const RAY_ANGLES = [-60, -30, 0, 30, 60];

function norm180(a) {
  while (a > 180) a -= 360;
  while (a < -180) a += 360;
  return a;
}

function clamp(v, lo, hi) {
  return v < lo ? lo : (v > hi ? hi : v);
}

function applyDeadband(v) {
  if (Math.abs(v) < 0.08) return 0;
  if (Math.abs(v) < 0.18) return v > 0 ? 0.18 : -0.18;
  return v;
}

function markObstacle(mem, x, y) {
  const cx = Math.floor(x / RES);
  const cy = Math.floor(y / RES);
  if (cx < 0 || cx >= GW || cy < 0 || cy >= GH) return;
  const rad = 1; // about 0.25 m inflation
  for (let dx = -rad; dx <= rad; dx++) {
    for (let dy = -rad; dy <= rad; dy++) {
      const nx = cx + dx;
      const ny = cy + dy;
      if (nx < 0 || nx >= GW || ny < 0 || ny >= GH) continue;
      mem.grid[ny * GW + nx] = 2;
    }
  }
}

function updateMap(mem, x, y, hTrue, rays) {
  const cx = Math.floor(x / RES);
  const cy = Math.floor(y / RES);
  if (cx >= 0 && cx < GW && cy >= 0 && cy < GH) {
    const id = cy * GW + cx;
    if (mem.grid[id] === 0) mem.grid[id] = 1;
  }
  for (let i = 0; i < 5; i++) {
    let d = rays[i];
    if (d > 9.5) d = 9.5;
    const rad = (hTrue + RAY_ANGLES[i]) * Math.PI / 180;
    const dx = Math.cos(rad);
    const dy = Math.sin(rad);
    for (let s = 0.2; s < d - 0.1; s += 0.2) {
      const px = x + dx * s;
      const py = y + dy * s;
      if (px < 0 || px >= 40 || py < 0 || py >= 40) break;
      const gx = Math.floor(px / RES);
      const gy = Math.floor(py / RES);
      if (gx >= 0 && gx < GW && gy >= 0 && gy < GH) {
        const id = gy * GW + gx;
        if (mem.grid[id] === 0) mem.grid[id] = 1;
      }
    }
    if (rays[i] < 9.5) {
      const px = x + dx * rays[i];
      const py = y + dy * rays[i];
      markObstacle(mem, px, py);
    }
  }
}

function planPath(mem, sx, sy, tx, ty) {
  const startX = Math.floor(sx / RES);
  const startY = Math.floor(sy / RES);
  let goalX = Math.floor(tx / RES);
  let goalY = Math.floor(ty / RES);
  if (startX < 0 || startX >= GW || startY < 0 || startY >= GH) return null;
  goalX = clamp(goalX, 0, GW - 1);
  goalY = clamp(goalY, 0, GH - 1);
  const start = startY * GW + startX;
  const goal = goalY * GW + goalX;
  mem.grid[start] = 1;
  if (start === goal) return [{ x: sx, y: sy }];

  const N = GW * GH;
  const g = mem.gScore;
  const came = mem.came;
  g.fill(Infinity);
  came.fill(-1);
  const open = mem.open;
  const openF = mem.openF;
  open.length = 0;
  openF.length = 0;

  function push(n, f) {
    open.push(n);
    openF.push(f);
    let i = open.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (openF[p] <= openF[i]) break;
      let tn = open[p]; open[p] = open[i]; open[i] = tn;
      let tf = openF[p]; openF[p] = openF[i]; openF[i] = tf;
      i = p;
    }
  }

  function pop() {
    const top = open[0];
    const last = open.pop();
    const lastF = openF.pop();
    if (open.length > 0) {
      open[0] = last;
      openF[0] = lastF;
      let i = 0;
      while (true) {
        const l = i * 2 + 1;
        const r = i * 2 + 2;
        let smallest = i;
        if (l < open.length && openF[l] < openF[smallest]) smallest = l;
        if (r < open.length && openF[r] < openF[smallest]) smallest = r;
        if (smallest === i) break;
        let tn = open[i]; open[i] = open[smallest]; open[smallest] = tn;
        let tf = openF[i]; openF[i] = openF[smallest]; openF[smallest] = tf;
        i = smallest;
      }
    }
    return top;
  }

  function heur(x1, y1, x2, y2) {
    const dx = Math.abs(x1 - x2);
    const dy = Math.abs(y1 - y2);
    return (dx + dy) + (Math.SQRT2 - 2) * Math.min(dx, dy);
  }

  g[start] = 0;
  push(start, heur(startX, startY, goalX, goalY));
  let iter = 0;
  while (open.length > 0 && iter++ < 25000) {
    const cur = pop();
    if (cur === goal) break;
    const cx = cur % GW;
    const cy = Math.floor(cur / GW);
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const nx = cx + dx;
        const ny = cy + dy;
        if (nx < 0 || nx >= GW || ny < 0 || ny >= GH) continue;
        const nid = ny * GW + nx;
        const cell = mem.grid[nid];
        if (cell === 2) continue;
        let step = (dx !== 0 && dy !== 0) ? 1.41421356 : 1;
        if (cell === 0) step += 0.6;
        const tentative = g[cur] + step;
        if (tentative < g[nid]) {
          came[nid] = cur;
          g[nid] = tentative;
          push(nid, tentative + heur(nx, ny, goalX, goalY));
        }
      }
    }
  }

  let targetNode = goal;
  if (came[goal] === -1 && goal !== start) {
    let best = -1;
    let bestH = Infinity;
    for (let i = 0; i < N; i++) {
      if (g[i] < Infinity) {
        const cx = i % GW;
        const cy = Math.floor(i / GW);
        const h = heur(cx, cy, goalX, goalY);
        if (h < bestH) {
          bestH = h;
          best = i;
        }
      }
    }
    if (best === -1) return null;
    targetNode = best;
  }

  const path = [];
  let cur = targetNode;
  while (cur !== -1) {
    const cx = cur % GW;
    const cy = Math.floor(cur / GW);
    path.push({ x: (cx + 0.5) * RES, y: (cy + 0.5) * RES });
    if (cur === start) break;
    cur = came[cur];
  }
  path.reverse();
  path[0] = { x: sx, y: sy };
  return path;
}

function clearLine(mem, x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const dist = Math.hypot(dx, dy);
  if (dist < 0.1) return true;
  const steps = Math.ceil(dist / 0.2);
  for (let i = 1; i < steps; i++) {
    const px = x1 + dx * i / steps;
    const py = y1 + dy * i / steps;
    const gx = Math.floor(px / RES);
    const gy = Math.floor(py / RES);
    if (gx < 0 || gx >= GW || gy < 0 || gy >= GH) continue;
    if (mem.grid[gy * GW + gx] === 2) return false;
  }
  return true;
}

function act(obs, mem) {
  if (!mem.init) {
    mem.init = true;
    mem.grid = new Uint8Array(GW * GH);
    for (let gx = 0; gx < GW; gx++) {
      for (let gy = 0; gy < GH; gy++) {
        const x = (gx + 0.5) * RES;
        const y = (gy + 0.5) * RES;
        if (x < 0.35 || x > 39.65 || y < 0.35 || y > 39.65) {
          mem.grid[gy * GW + gx] = 2;
        }
      }
    }
    mem.gScore = new Float32Array(GW * GH);
    mem.came = new Int32Array(GW * GH);
    mem.open = [];
    mem.openF = [];
    mem.bias = 0;
    mem.biasN = 0;
    mem.lastBiasT = obs.t;
    mem.lastBiasX = obs.x;
    mem.lastBiasY = obs.y;
    mem.lastBiasHeading = obs.heading;
    mem.fx = obs.x;
    mem.fy = obs.y;
    mem.path = null;
    mem.pathIndex = 0;
    mem.lastPlan = -1;
    mem.lastTargetIndex = -1;
    mem.lastProgressT = obs.t;
    mem.lastDist = 1e9;
    mem.recoverUntil = 0;
    mem.recoverSteer = 0.5;
    mem.stuckT = obs.t;
  }

  const t = obs.t;
  mem.fx += 0.5 * (obs.x - mem.fx);
  mem.fy += 0.5 * (obs.y - mem.fy);
  const px = mem.fx;
  const py = mem.fy;

  if (t - mem.lastBiasT > 0.5) {
    const dx = px - mem.lastBiasX;
    const dy = py - mem.lastBiasY;
    const dist = Math.hypot(dx, dy);
    if (dist > 0.2 && obs.speed > 0.2 && Math.abs(norm180(obs.heading - mem.lastBiasHeading)) < 10) {
      const moveHeading = Math.atan2(dy, dx) * 180 / Math.PI;
      const biasObs = norm180(obs.heading - moveHeading);
      if (mem.biasN === 0) mem.bias = biasObs;
      else mem.bias = 0.9 * mem.bias + 0.1 * biasObs;
      mem.bias = clamp(mem.bias, -60, 60);
      mem.biasN++;
    }
    mem.lastBiasT = t;
    mem.lastBiasX = px;
    mem.lastBiasY = py;
    mem.lastBiasHeading = obs.heading;
  }

  const hTrue = norm180(obs.heading - mem.bias);
  updateMap(mem, px, py, hTrue, obs.rays);

  const tx = obs.targetX;
  const ty = obs.targetY;
  const distToTarget = Math.hypot(tx - px, ty - py);

  if (obs.targetIndex !== mem.lastTargetIndex) {
    mem.lastTargetIndex = obs.targetIndex;
    mem.path = null;
    mem.pathIndex = 0;
    mem.lastPlan = -1;
    mem.lastProgressT = t;
    mem.lastDist = distToTarget;
  }

  if (t - mem.lastPlan > 1.0 || mem.path === null) {
    mem.path = planPath(mem, px, py, tx, ty);
    mem.pathIndex = 0;
    mem.lastPlan = t;
  }

  let aimX = tx;
  let aimY = ty;
  if (mem.path && mem.path.length > 0) {
    while (mem.pathIndex < mem.path.length - 1 &&
           Math.hypot(px - mem.path[mem.pathIndex].x, py - mem.path[mem.pathIndex].y) < 0.5) {
      mem.pathIndex++;
    }
    let bestIdx = mem.pathIndex;
    for (let i = mem.pathIndex; i < mem.path.length; i++) {
      const d = Math.hypot(px - mem.path[i].x, py - mem.path[i].y);
      if (d > 3.5) break;
      if (clearLine(mem, px, py, mem.path[i].x, mem.path[i].y)) {
        bestIdx = i;
      } else {
        break;
      }
    }
    mem.pathIndex = bestIdx;
    aimX = mem.path[bestIdx].x;
    aimY = mem.path[bestIdx].y;
  }

  const aimAngle = Math.atan2(aimY - py, aimX - px) * 180 / Math.PI;
  let err = norm180(aimAngle - hTrue);

  let turn = clamp(err * Math.PI / 180 * 0.8, -0.6, 0.6);
  let base = 0.55;
  if (Math.abs(err) > 45) base *= 0.6;
  if (Math.abs(err) > 90) base *= 0.5;

  const front = obs.rays[2];
  const leftClear = obs.rays[3] + obs.rays[4];
  const rightClear = obs.rays[0] + obs.rays[1];

  let avoid = 0;
  if (front < 1.2) {
    if (leftClear > rightClear + 0.5) avoid = 0.6;
    else if (rightClear > leftClear + 0.5) avoid = -0.6;
    else avoid = (leftClear - rightClear) * 0.3;
  }
  for (let i = 0; i < 5; i++) {
    const d = obs.rays[i];
    if (d < 1.0) {
      const w = (1.0 - d) / 1.0;
      avoid -= (RAY_ANGLES[i] / 60) * w * 0.5;
