  if (px < 0.8) wallTurn += norm180(0 - hTrue) * (0.8 - px) * 2;
  if (px > 39.2) wallTurn += norm180(180 - hTrue) * (px - 39.2) * 2;
  if (py < 0.8) wallTurn += norm180(90 - hTrue) * (0.8 - py) * 2;
  if (py > 39.2) wallTurn += norm180(-90 - hTrue) * (py - 39.2) * 2;
  if (Math.abs(wallTurn) > 5) {
    turn = clamp(turn + clamp(wallTurn * Math.PI / 180 * 0.5, -0.5, 0.5), -0.8, 0.8);
    base = Math.min(base, 0.4);
  }

  let minRay = Math.min(front, obs.rays[0], obs.rays[1], obs.rays[3], obs.rays[4]);
  if (minRay < 0.4) {
    base = -0.2;
    turn = avoid;
  }

  if (distToTarget < mem.lastDist - 0.1) {
    mem.lastDist = distToTarget;
    mem.lastProgressT = t;
  }
  if (t - mem.lastProgressT > 3.0 && distToTarget > 1.0) {
    mem.recoverUntil = t + 2.0;
    mem.recoverSteer = (leftClear > rightClear) ? 0.5 : -0.5;
