    if (t - mem.stuckT > 1.0) {
      mem.recoverUntil = t + 1.5;
      mem.recoverSteer = (leftClear > rightClear) ? 0.5 : -0.5;
      mem.stuckT = t;
    }
  } else {
    mem.stuckT = t;
  }

  let left = base - turn;
  let right = base + turn;
  left = applyDeadband(left);
  right = applyDeadband(right);
  left = clamp(left, -1, 1);
  right = clamp(right, -1, 1);

  return { left, right };
}

const RES = 0.5;
