function norm180(a) {
  while (a > 180) a -= 360;
  while (a < -180) a += 360;
  return a;
}

function clamp(v, lo, hi) {
  return v < lo ? lo : (v > hi ? hi : v);
}

function applyDeadband(v) {
  if (Math.abs(v) < 0.08) return 0;
  if (Math.abs(v) < 0.15) return v > 0 ? 0.15 : -0.15;
  return v;
}

function markObstacle(mem, x, y) {
  const cx = Math.floor(x / RES);
  const cy = Math.floor(y / RES);
