function updateMap(mem, x, y, hTrue, rays) {
  const cx = Math.floor(x / RES);
  const cy = Math.floor(y / RES);
  if (cx >= 0 && cx < GW && cy >= 0 && cy < GH) {
    const id = cy * GW + cx;
    if (mem.grid[id] === 0) mem.grid[id] = 1;
  }
  for (let i = 0; i < 5; i++) {
    let d = rays[i];
    if (d > 9.5) d = 9.5;
    const rad = (hTrue + RAY_ANGLES[i]) * Math.PI / 180;
    const dx = Math.cos(rad);
    const dy = Math.sin(rad);
    for (let s = 0.3; s < d - 0.2; s += 0.3) {
      const px = x + dx * s;
      const py = y + dy * s;
      if (px < 0 || px >= 40 || py < 0 || py >= 40) break;
      const gx = Math.floor(px / RES);
      const gy = Math.floor(py / RES);
      if (gx >= 0 && gx < GW && gy >= 0 && gy < GH) {
        const id = gy * GW + gx;
        if (mem.grid[id] === 0) mem.grid[id] = 1;
      }
    }
    if (rays[i] < 9.5) {
      const px = x + dx * rays[i];
      const py = y + dy * rays[i];
      markObstacle(mem, px, py);
    }
  }
}

function planPath(mem, sx, sy, tx, ty) {
