  const N = GW * GH;
  const g = mem.gScore;
  const came = mem.came;
  g.fill(Infinity);
  came.fill(-1);
  const open = mem.open;
  const openF = mem.openF;
  open.length = 0;
  openF.length = 0;

  function push(n, f) {
    open.push(n);
    openF.push(f);
    let i = open.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (openF[p] <= openF[i]) break;
      let tn = open[p]; open[p] = open[i]; open[i] = tn;
      let tf = openF[p]; openF[p] = openF[i]; openF[i] = tf;
      i = p;
    }
  }
  function pop() {
    const top = open[0];
    const last = open.pop();
    const lastF = openF.pop();
    if (open.length > 0) {
      open[0] = last;
      openF[0] = lastF;
      let i = 0;
      while (true) {
        const l = i * 2 + 1;
        const r = i * 2 + 2;
        let smallest = i;
        if (l < open.length && openF[l] < openF[smallest]) smallest = l;
        if (r < open.length && openF[r] < openF[smallest]) smallest = r;
        if (smallest === i) break;
        let tn = open[i]; open[i] = open[smallest]; open[smallest] = tn;
        let tf = openF[i]; openF[i] = openF[smallest]; openF[smallest] = tf;
        i = smallest;
      }
    }
    return top;
  }
  function heur(x1, y1, x2, y2) {
    const dx = Math.abs(x1 - x2);
    const dy = Math.abs(y1 - y2);
    return (dx + dy) + (Math.SQRT2 - 2) * Math.min(dx, dy);
  }

  g[start] = 0;
  push(start, heur(startX, startY, goalX, goalY));
  let iter = 0;
  while (open.length > 0 && iter++ < 8000) {
    const cur = pop();
    if (cur === goal) break;
    const cx = cur % GW;
    const cy = Math.floor(cur / GW);
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        const nx = cx + dx;
        const ny = cy + dy;
        if (nx < 0 || nx >= GW || ny < 0 || ny >= GH) continue;
        const nid = ny * GW + nx;
        const cell = mem.grid[nid];
        if (cell === 2) continue;
        let step = (dx !== 0 && dy !== 0) ? 1.41421356 : 1;
        if (cell === 0) step += 0.4;
        const tentative = g[cur] + step;
        if (tentative < g[nid]) {
          came[nid] = cur;
