  let targetNode = goal;
  if (came[goal] === -1 && goal !== start) {
    let best = -1;
    let bestH = Infinity;
    for (let i = 0; i < N; i++) {
      if (g[i] < Infinity) {
        const cx = i % GW;
        const cy = Math.floor(i / GW);
        const h = heur(cx, cy, goalX, goalY);
        if (h < bestH) {
          bestH = h;
          best = i;
        }
      }
    }
