    targetNode = best;
  }

  const path = [];
  let cur = targetNode;
  while (cur !== -1) {
    const cx = cur % GW;
    const cy = Math.floor(cur / GW);
    path.push({ x: (cx + 0.5) * RES, y: (cy + 0.5) * RES });
    if (cur === start) break;
    cur = came[cur];
  }
  path.reverse();
  path[0] = { x: sx, y: sy };
  return path;
}

