  const steps = Math.ceil(dist / 0.15);
  for (let i = 1; i < steps; i++) {
    const px = x1 + dx * i / steps;
    const py = y1 + dy * i / steps;
    const gx = Math.floor(px / RES);
    const gy = Math.floor(py / RES);
    if (gx < 0 || gx >= GW || gy < 0 || gy >= GH) return false;
