    mem.recoverTurn = 0;
    mem.lastTurn = 0;
    mem.calibUntil = t + 0.4;
  }

  mem.fx += 0.25 * (obs.x - mem.fx);
  mem.fy += 0.25 * (obs.y - mem.fy);
  const px = mem.fx;
  const py = mem.fy;

  const dt = t - mem.lastGpsT;
  if (dt > 0.02) {
    const dx = obs.x - mem.lastGpsX;
    const dy = obs.y - mem.lastGpsY;
    const instVx = dx / dt;
    const instVy = dy / dt;
    if (Math.hypot(instVx, instVy) < 5) {
      mem.vx = 0.9 * mem.vx + 0.1 * instVx;
      mem.vy = 0.9 * mem.vy + 0.1 * instVy;
    }
    mem.lastGpsX = obs.x;
    mem.lastGpsY = obs.y;
    mem.lastGpsT = t;
  }

  const vSpeed = Math.hypot(mem.vx, mem.vy);
  if (vSpeed > 0.25 && Math.abs(mem.lastTurn) < 0.25) {
    const moveHeading = Math.atan2(mem.vy, mem.vx) * 180 / Math.PI;
    const biasObs = norm180(obs.heading - moveHeading);
    if (mem.biasN === 0) {
      mem.bias = biasObs;
      resetGrid(mem);
    } else {
      const diff = norm180(biasObs - mem.bias);
      if (Math.abs(diff) > 60) {
        mem.bias = biasObs;
        resetGrid(mem);
      } else {
        mem.bias = norm180(mem.bias + 0.05 * diff);
      }
    }
    mem.biasN++;
  }
  const hEst = norm180(obs.heading - mem.bias);

  updateMap(mem, px, py, hEst, obs.rays);

  const tx = obs.targetX;
  const ty = obs.targetY;
  const distToTarget = Math.hypot(tx - px, ty - py);

  if (obs.targetIndex !== mem.lastTargetIndex) {
    mem.lastTargetIndex = obs.targetIndex;
    mem.path = null;
    mem.lastPlan = -99;
    mem.stuckT = t;
  }

  if (mem.path === null || t - mem.lastPlan > 1.0) {
    if (distToTarget < 2.0) {
      mem.path = [{ x: tx, y: ty }];
    } else {
      mem.path = planPath(mem, px, py, tx, ty);
    }
    mem.lastPlan = t;
  }

  let carrotX = tx;
  let carrotY = ty;
  if (mem.path && mem.path.length > 0 && distToTarget > 1.2) {
    let ci = 0;
    let bestD = 1e9;
    for (let i = 0; i < mem.path.length; i++) {
      const d = Math.hypot(px - mem.path[i].x, py - mem.path[i].y);
      if (d < bestD) {
        bestD = d;
        ci = i;
      }
    }
    const L = 1.2;
    let acc = 0;
    carrotX = mem.path[ci].x;
    carrotY = mem.path[ci].y;
    for (let i = ci; i < mem.path.length - 1; i++) {
      const d = Math.hypot(mem.path[i + 1].x - mem.path[i].x, mem.path[i + 1].y - mem.path[i].y);
      if (acc + d >= L) {
        const r = (L - acc) / d;
        carrotX = mem.path[i].x + (mem.path[i + 1].x - mem.path[i].x) * r;
        carrotY = mem.path[i].y + (mem.path[i + 1].y - mem.path[i].y) * r;
        break;
      }
      acc += d;
      carrotX = mem.path[i + 1].x;
      carrotY = mem.path[i + 1].y;
    }
  }

  const desired = Math.atan2(carrotY - py, carrotX - px) * 180 / Math.PI;
  const err = norm180(desired - hEst);

  const front = obs.rays[2];
  const leftClear = obs.rays[3] + obs.rays[4];
  const rightClear = obs.rays[0] + obs.rays[1];

  let base, turn;

  const sideMin = Math.min(obs.rays[0], obs.rays[1], obs.rays[3], obs.rays[4]);
  if (t < mem.calibUntil && front > 1.5 && sideMin > 1.0) {
    base = 0.6;
    turn = 0;
  } else {
    turn = clamp(err * 0.01, -0.6, 0.6);
    base = 0.75;
    if (Math.abs(err) > 20) base = 0.55;
    if (Math.abs(err) > 50) base = 0.35;
    if (Math.abs(err) > 90) base = 0.2;

    if (distToTarget < 1.5) base = Math.min(base, 0.4);
    if (distToTarget < 0.8) base = Math.min(base, 0.3);

    if (front < 2.0) {
      const avoid = clamp((leftClear - rightClear) * 0.4, -0.7, 0.7);
      const w = clamp((2.0 - front) / 1.5, 0, 1);
      turn = clamp(turn * (1 - w * 0.8) + avoid * w, -0.9, 0.9);
      base = Math.min(base, 0.7 - 0.4 * w);
    }

    if (obs.rays[0] < 0.7) { turn += 0.3; base = Math.min(base, 0.45); }
    if (obs.rays[1] < 0.7) { turn += 0.15; base = Math.min(base, 0.5); }
    if (obs.rays[3] < 0.7) { turn -= 0.15; base = Math.min(base, 0.5); }
    if (obs.rays[4] < 0.7) { turn -= 0.3; base = Math.min(base, 0.45); }

    if (front < 0.5) {
      if (leftClear < 1.2 && rightClear < 1.2) {
        base = -0.25;
        turn = leftClear > rightClear ? 0.4 : -0.4;
        mem.recoverUntil = Math.max(mem.recoverUntil, t + 0.25);
      } else {
        base = Math.min(base, 0.15);
        turn += (leftClear - rightClear) * 0.5;
      }
    }

    let wallTurn = 0;
    const margin = 1.0;
    if (px < margin) {
      wallTurn += norm180(0 - hEst) * ((margin - px) / margin);
      base = Math.min(base, 0.5);
    }
    if (px > 40 - margin) {
      wallTurn += norm180(180 - hEst) * ((px - (40 - margin)) / margin);
      base = Math.min(base, 0.5);
    }
    if (py < margin) {
      wallTurn += norm180(90 - hEst) * ((margin - py) / margin);
      base = Math.min(base, 0.5);
    }
    if (py > 40 - margin) {
      wallTurn += norm180(-90 - hEst) * ((py - (40 - margin)) / margin);
      base = Math.min(base, 0.5);
    }
    if (Math.abs(wallTurn) > 1) {
      turn += clamp(wallTurn * 0.008, -0.5, 0.5);
    }

    if (obs.speed < 0.08 && base > 0.1 && t - mem.stuckT > 1.2) {
      mem.recoverUntil = t + 0.7;
      mem.recoverTurn = leftClear > rightClear ? 0.5 : -0.5;
      mem.stuckT = t;
    }

    if (t < mem.recoverUntil) {
      if (t < mem.recoverUntil - 0.3) {
        base = -0.3;
        turn = 0;
      } else {
        base = 0.15;
        turn = mem.recoverTurn;
      }
    } else if (obs.speed > 0.2) {
      mem.stuckT = t;
    }
  }

  turn = clamp(turn, -0.9, 0.9);
  base = clamp(base, -0.4, 0.9);

  let left = base - turn;
  let right = base + turn;
  left = applyDeadband(left);
  right = applyDeadband(right);
  left = clamp(left, -1, 1);
  right = clamp(right, -1, 1);

  mem.lastTurn = turn;
  return { left: left, right: right };
}

const RES = 0.5, GW = 80, GH = 80, N = GW * GH;
const RAY = [-60, -30, 0, 30, 60];

function norm180(a) {
  while (a > 180) a -= 360;
  while (a < -180) a += 360;
  return a;
}
function clamp(v, a, b) {
  return v < a ? a : (v > b ? b : v);
}
function db(v) {
  if (Math.abs(v) < 0.05) return 0;
  if (Math.abs(v) < 0.12) return v > 0 ? 0.12 : -0.12;
  return v;
}

function updateMap(mem, x, y, h, rays) {
  let cx = Math.floor(x / RES), cy = Math.floor(y / RES);
  if (cx >= 0 && cx < GW && cy >= 0 && cy < GH) {
    let id = cy * GW + cx;
    if (mem.grid[id] === 0) mem.grid[id] = 1;
  }
  for (let i = 0; i < 5; i++) {
    let d = rays[i];
    let rad = (h + RAY[i]) * Math.PI / 180;
    let dx = Math.cos(rad), dy = Math.sin(rad);
    let maxS = d < 9.5 ? d - 0.15 : 4.0;
    for (let s = 0.3; s < maxS; s += 0.4) {
      let px = x + dx * s, py = y + dy * s;
      if (px < 0 || px >= 40 || py < 0 || py >= 40) break;
      let gx = Math.floor(px / RES), gy = Math.floor(py / RES);
      if (gx >= 0 && gx < GW && gy >= 0 && gy < GH) {
        let id = gy * GW + gx;
        if (mem.grid[id] === 0) mem.grid[id] = 1;
      }
    }
    if (d < 9.5) {
      let px = x + dx * d, py = y + dy * d;
      let gx = Math.floor(px / RES), gy = Math.floor(py / RES);
      if (gx >= 0 && gx < GW && gy >= 0 && gy < GH) {
        mem.grid[gy * GW + gx] = 2;
      }
    }
  }
}

function planPath(mem, px, py, tx, ty) {
  let sx = clamp(Math.floor(px / RES), 0, GW - 1);
  let sy = clamp(Math.floor(py / RES), 0, GH - 1);
