  const goal = gy * GW + gx;
  if (start === goal) return [{ x: px, y: py }];

  if (mem.grid[start] === 2) mem.grid[start] = 1;
  if (mem.grid[goal] === 2) mem.grid[goal] = 1;

  const g = mem.g;
  const came = mem.came;
  g.fill(Infinity);
  came.fill(-1);

  const open = mem.open;
  const openF = mem.openF;
  open.length = 0;
  openF.length = 0;

  function push(n, f) {
    open.push(n);
    openF.push(f);
    let i = open.length - 1;
    while (i > 0) {
      let p = (i - 1) >> 1;
      if (openF[p] <= openF[i]) break;
      let tn = open[p]; open[p] = open[i]; open[i] = tn;
      let tf = openF[p]; openF[p] = openF[i]; openF[i] = tf;
      i = p;
    }
  }
  function pop() {
    const top = open[0];
    const last = open.pop();
    const lastF = openF.pop();
    if (open.length > 0) {
      open[0] = last;
      openF[0] = lastF;
      let i = 0;
      while (true) {
        let l = i * 2 + 1, r = i * 2 + 2, s = i;
        if (l < open.length && openF[l] < openF[s]) s = l;
        if (r < open.length && openF[r] < openF[s]) s = r;
        if (s === i) break;
        let tn = open[i]; open[i] = open[s]; open[s] = tn;
        let tf = openF[i]; openF[i] = openF[s]; openF[s] = tf;
        i = s;
      }
    }
    return top;
  }
  function heur(x1, y1, x2, y2) {
    let dx = Math.abs(x1 - x2), dy = Math.abs(y1 - y2);
    return (dx + dy) + (Math.SQRT2 - 2) * Math.min(dx, dy);
  }

  g[start] = 0;
  push(start, heur(sx, sy, gx, gy));
  let iter = 0;

  while (open.length > 0 && iter++ < 4000) {
    let cur = pop();
    if (cur === goal) break;
    let cx = cur % GW;
    let cy = (cur - cx) / GW;

    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        if (dx === 0 && dy === 0) continue;
        let nx = cx + dx, ny = cy + dy;
        if (nx < 0 || nx >= GW || ny < 0 || ny >= GH) continue;
        let nid = ny * GW + nx;
        if (mem.grid[nid] === 2) continue;

        let step = (dx !== 0 && dy !== 0) ? 1.41421356 : 1;
        if (mem.grid[nid] === 0) step += 0.4;
        if ((nx > 0 && mem.grid[nid - 1] === 2) ||
            (nx < GW - 1 && mem.grid[nid + 1] === 2) ||
            (ny > 0 && mem.grid[nid - GW] === 2) ||
            (ny < GH - 1 && mem.grid[nid + GW] === 2)) {
          step += 0.6;
        }

        let tentative = g[cur] + step;
        if (tentative < g[nid]) {
          came[nid] = cur;
          g[nid] = tentative;
          push(nid, tentative + heur(nx, ny, gx, gy));
        }
      }
    }
  }

  let targetNode = goal;
  if (came[goal] === -1 && goal !== start) {
    let best = -1, bestH = Infinity;
    for (let i = 0; i < N; i++) {
      if (g[i] < Infinity) {
        let cx = i % GW;
        let cy = (i - cx) / GW;
        let hh = heur(cx, cy, gx, gy);
        if (hh < bestH) {
          bestH = hh;
          best = i;
        }
      }
    }
    if (best === -1) return null;
    targetNode = best;
  }

  const path = [];
  let cur = targetNode;
  while (cur !== -1) {
    let cx = cur % GW;
    let cy = (cur - cx) / GW;
    path.push({ x: (cx + 0.5) * RES, y: (cy + 0.5) * RES });
    if (cur === start) break;
    cur = came[cur];
  }
  path.reverse();
  path[0] = { x: px, y: py };
  return path;
}

function act(obs, mem) {
  const t = obs.t;

  if (!mem.init) {
    mem.init = true;
    mem.grid = new Uint8Array(N);
    mem.g = new Float32Array(N);
    mem.came = new Int32Array(N);
    mem.open = [];
    mem.openF = [];
    mem.bias = 0;
    mem.calibDone = false;
    mem.startX = obs.x;
    mem.startY = obs.y;
    mem.x = obs.x;
    mem.y = obs.y;
    mem.lastBiasT = t;
    mem.lastBiasX = obs.x;
    mem.lastBiasY = obs.y;
    mem.lastTurn = 0;
    mem.path = null;
    mem.pathTime = -99;
    mem.lastTargetIndex = -1;
    mem.stuckCheckT = t;
    mem.stuckX = obs.x;
    mem.stuckY = obs.y;
