    let ddx = mem.x - mem.lastBiasX;
    let ddy = mem.y - mem.lastBiasY;
    let dist = Math.hypot(ddx, ddy);
    if (dist > 0.3 && obs.speed > 0.4 && Math.abs(mem.lastTurn) < 0.15) {
      let moveHeading = Math.atan2(ddy, ddx) * 180 / Math.PI;
      let biasObs = norm180(obs.heading - moveHeading);
      let diff = norm180(biasObs - mem.bias);
      if (Math.abs(diff) < 25) mem.bias = norm180(mem.bias + 0.1 * diff);
      else if (Math.abs(diff) < 90) mem.bias = norm180(mem.bias + 0.03 * diff);
    }
    mem.lastBiasT = t;
    mem.lastBiasX = mem.x;
    mem.lastBiasY = mem.y;
  }

  const tx = obs.targetX;
  const ty = obs.targetY;
  const distToTarget = Math.hypot(tx - px, ty - py);

  if (obs.targetIndex !== mem.lastTargetIndex) {
    mem.lastTargetIndex = obs.targetIndex;
    mem.path = null;
    mem.pathTime = -99;
    mem.stuckCheckT = t;
    mem.stuckX = px;
    mem.stuckY = py;
  }

  if (distToTarget < 1.2) {
    mem.path = null;
  } else if (!mem.path || t - mem.pathTime > 0.8) {
    let p = planPath(mem, px, py, tx, ty);
    mem.path = p || [{ x: tx, y: ty }];
    mem.pathTime = t;
