        ci = i;
      }
    }
    let acc = 0;
    aimX = mem.path[ci].x;
    aimY = mem.path[ci].y;
    for (let i = ci; i < mem.path.length - 1; i++) {
      let d = Math.hypot(mem.path[i + 1].x - mem.path[i].x,
                         mem.path[i + 1].y - mem.path[i].y);
      if (acc + d >= 0.9) {
        let r = (0.9 - acc) / d;
        aimX = mem.path[i].x + (mem.path[i + 1].x - mem.path[i].x) * r;
        aimY = mem.path[i].y + (mem.path[i + 1].y - mem.path[i].y) * r;
        break;
      }
      acc += d;
      aimX = mem.path[i + 1].x;
      aimY = mem.path[i + 1].y;
    }
