  let desired = Math.atan2(aimY - py, aimX - px) * 180 / Math.PI;
  let err = norm180(desired - h);

  let base = 0.8;
  if (Math.abs(err) > 30) base = 0.55;
  if (Math.abs(err) > 60) base = 0.35;
  if (Math.abs(err) > 100) base = 0.2;
  let turn = clamp(err * 0.006, -0.35, 0.35);

  if (distToTarget < 1.5) base = Math.min(base, 0.45);
  if (distToTarget < 0.8) base = Math.min(base, 0.3);

  const front = obs.rays[2];
  const leftClear = obs.rays[3] + obs.rays[4];
  const rightClear = obs.rays[0] + obs.rays[1];

  if (front < 1.5) {
    let w = clamp((1.5 - front) / 1.2, 0, 1);
    let avoid = clamp((leftClear - rightClear) * 0.4, -0.6, 0.6);
    turn = clamp(turn * (1 - w * 0.6) + avoid * w, -0.7, 0.7);
    base = Math.min(base, 0.75 - 0.45 * w);
  }
  if (front < 0.55) {
    if (leftClear < 0.8 && rightClear < 0.8) {
      base = -0.2;
      turn = leftClear > rightClear ? 0.4 : -0.4;
    } else {
      base = Math.min(base, 0.15);
      turn = clamp(turn + (leftClear - rightClear) * 0.5, -0.8, 0.8);
    }
  }

  if (obs.rays[0] < 0.7) { turn += 0.15; base = Math.min(base, 0.5); }
  if (obs.rays[1] < 0.7) { turn += 0.08; base = Math.min(base, 0.55); }
  if (obs.rays[3] < 0.7) { turn -= 0.08; base = Math.min(base, 0.55); }
  if (obs.rays[4] < 0.7) { turn -= 0.15; base = Math.min(base, 0.5); }

  const margin = 0.8;
  let wallTurn = 0;
  if (px < margin) wallTurn += norm180(0 - h) * ((margin - px) / margin);
  if (px > 40 - margin) wallTurn += norm180(180 - h) * ((px - (40 - margin)) / margin);
  if (py < margin) wallTurn += norm180(90 - h) * ((margin - py) / margin);
  if (py > 40 - margin) wallTurn += norm180(-90 - h) * ((py - (40 - margin)) / margin);
  if (Math.abs(wallTurn) > 0.1) {
    turn += clamp(wallTurn * 0.01, -0.4, 0.4);
    base = Math.min(base, 0.6);
  }

  if (t - mem.stuckCheckT > 0.8) {
    let moved = Math.hypot(px - mem.stuckX, py - mem.stuckY);
    if (moved < 0.1 && obs.speed < 0.15 && distToTarget > 1.0 && t > mem.recoverUntil) {
      mem.recoverUntil = t + 0.7;
      mem.recoverTurn = leftClear > rightClear ? 0.5 : -0.5;
    }
    mem.stuckCheckT = t;
    mem.stuckX = px;
    mem.stuckY = py;
  }

  if (t < mem.recoverUntil) {
    if (t < mem.recoverUntil - 0.35) {
      base = -0.25;
      turn = 0;
    } else {
      base = 0.25;
      turn = mem.recoverTurn;
    }
  }

  turn = clamp(turn, -0.9, 0.9);
  base = clamp(base, -0.3, 0.9);

  let left = base - turn;
  let right = base + turn;
  left = clamp(db(left), -1, 1);
  right = clamp(db(right), -1, 1);

