    mem.bias = 0;
    mem.calibDone = false;
    mem.startX = obs.x;
    mem.startY = obs.y;
    mem.x = obs.x;
    mem.y = obs.y;
    mem.lastX = obs.x;
    mem.lastY = obs.y;
    mem.lastT = t;
    mem.vx = 0;
    mem.vy = 0;
    mem.lastTurn = 0;
    mem.stuckT = t;
    mem.stuckX = obs.x;
    mem.stuckY = obs.y;
    mem.recoverUntil = 0;
    mem.recoverTurn = 0;
    mem.recoverBase = 0;
    mem.lastTargetIndex = -1;
  }

  // Initial calibration: drive straight for 1s if possible.
  if (!mem.calibDone) {
    if (t < 1.0 && obs.rays[2] > 1.5) {
      return { left: 0.6, right: 0.6 };
    } else {
      const dx = obs.x - mem.startX;
      const dy = obs.y - mem.startY;
      if (Math.hypot(dx, dy) > 0.3) {
        const moveH = Math.atan2(dy, dx) * 180 / Math.PI;
        mem.bias = norm180(obs.heading - moveH);
      } else {
        mem.bias = 0;
      }
      mem.calibDone = true;
      mem.x = obs.x;
      mem.y = obs.y;
      mem.lastX = obs.x;
      mem.lastY = obs.y;
      mem.lastT = t;
    }
